PAGES['help']['sections'].append({'title':'검색 화면과 결과 화면','paragraphs':['첫 화면의 중앙 검색창에서 조건을 입력하면 결과 화면으로 이동합니다. 대사 검색으로 버튼이나 브라우저 뒤로 가기로 돌아가면 입력한 조건이 유지됩니다. 결과 주소를 새로고침하거나 공유하면 같은 조건으로 검색합니다.','기기의 모션 줄이기 설정을 사용하면 화면 전환과 반복 애니메이션을 최소화합니다.']})
PAGES['changelog']['sections'].insert(0,{'title':'2026-10-22 · 중앙 검색과 결과 페이지','paragraphs':['중앙 검색 화면과 결과 화면을 분리하고 검색 조건을 유지하는 돌아가기, 브라우저 뒤로·앞으로 이동을 지원합니다.','버튼·입력창·카드 디자인을 통일하고 검색 로딩, 자동완성, 호버와 화면 이동 애니메이션을 추가했습니다. 모션 줄이기 설정을 존중합니다.']})
